package com.example.starter.api;

import java.util.Map;

import jakarta.validation.Valid;

import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import com.example.starter.api.dto.ColorCheckRequest;
import com.example.starter.api.dto.CreateRecipeRequest;
import com.example.starter.api.dto.FeedRequest;
import com.example.starter.api.dto.JudgeRequest;
import com.example.starter.api.dto.LateColorRequest;
import com.example.starter.api.dto.MergeLotsRequest;
import com.example.starter.api.dto.ScheduleLotRequest;
import com.example.starter.service.DyeService;

/**
 * 印染配方服务 REST 入口。
 */
@RestController
@RequestMapping("/api")
public class DyeController {

    private final DyeService dyeService;

    public DyeController(DyeService dyeService) {
        this.dyeService = dyeService;
    }

    @PostMapping("/recipes")
    public ResponseEntity<Map<String, Object>> createRecipe(@Valid @RequestBody CreateRecipeRequest req) {
        return ResponseEntity.status(HttpStatus.CREATED).body(dyeService.createRecipe(req));
    }

    @PostMapping("/recipes/{recipeCode}/publish")
    public Map<String, Object> publishRecipe(@PathVariable String recipeCode) {
        return dyeService.publishRecipe(recipeCode);
    }

    @PostMapping("/color-checks")
    public Map<String, Object> colorCheck(@Valid @RequestBody ColorCheckRequest req) {
        return dyeService.colorCheck(req);
    }

    @PostMapping("/lots")
    public ResponseEntity<Map<String, Object>> scheduleLot(@Valid @RequestBody ScheduleLotRequest req) {
        return ResponseEntity.status(HttpStatus.CREATED).body(dyeService.scheduleLot(req));
    }

    @PostMapping("/lots/merge")
    public Map<String, Object> mergeLots(@Valid @RequestBody MergeLotsRequest req) {
        return dyeService.mergeLots(req);
    }

    @PostMapping("/feedings")
    public Map<String, Object> feed(@Valid @RequestBody FeedRequest req) {
        return dyeService.feed(req);
    }

    @PostMapping("/judgments")
    public Map<String, Object> judge(@Valid @RequestBody JudgeRequest req) {
        return dyeService.judge(req);
    }

    @PostMapping("/lots/{lotNo}/archive")
    public Map<String, Object> archiveLot(@PathVariable String lotNo) {
        return dyeService.archiveLot(lotNo);
    }

    @PostMapping("/lots/{lotNo}/late-color")
    public Map<String, Object> receiveLateColor(@PathVariable String lotNo,
                                                @Valid @RequestBody LateColorRequest req) {
        return dyeService.receiveLateColor(lotNo, req);
    }

    @GetMapping("/lots/{lotNo}")
    public Map<String, Object> getLot(@PathVariable String lotNo) {
        return dyeService.getLot(lotNo);
    }

    @GetMapping("/recipes/{recipeCode}/recalculate")
    public Map<String, Object> recalculate(@PathVariable String recipeCode) {
        return dyeService.recalculate(recipeCode);
    }
}

